//! The engine's built-in files.
//!
//! The original engine links a handful of files into its executable and
//! serves them when no loose file and no package has the name
//! (`CBResourceFile::Open`, the `GF_RES` resources): the fallback system
//! font, the placeholder shown for a missing image or sprite, the default
//! shadow of 3D actors and the marker of a waypoint. Games name them like
//! any other file (`system_font.fnt`, `invalid.bmp`).
//!
//! The files here have the same names and the same roles, but none of
//! them is the original's: every image is generated by this module, the
//! font from a plain 5x7 dot-matrix alphabet drawn for Luma, and the two
//! definitions are written for these images. A game therefore gets a
//! readable fallback font and a visible placeholder, not the original's
//! pixels.
//!
//! [`register`] adds them to a game's file system; `World` does it when
//! it opens a game.

use luma_archive::Vfs;
use luma_formats::Image;

/// The fallback system font (`CBGame::LoadBuffer` loads it when the game
/// names no system font, or one that cannot be loaded).
pub const SYSTEM_FONT: &str = "system_font.fnt";

/// The image shown for a missing image or sprite (`CBSprite::LoadFile`,
/// `CBSurfaceStorage::AddSurface`).
pub const INVALID_IMAGE: &str = "invalid.bmp";

/// The image of the 3D actors' simple shadows when the game names none.
pub const SHADOW_IMAGE: &str = "shadow.png";

/// Adds the built-in files to a file system.
pub fn register(vfs: &mut Vfs) {
    vfs.add_resource(SYSTEM_FONT, SYSTEM_FONT_DEFINITION.as_bytes().to_vec());
    vfs.add_resource("system_font.bmp", bmp(&system_font_image()));
    vfs.add_resource(INVALID_IMAGE, bmp(&invalid_image([200, 0, 0])));
    vfs.add_resource("invalid_debug.bmp", bmp(&invalid_image([0, 0, 200])));
    vfs.add_resource("wpt.bmp", bmp(&waypoint_image()));
    vfs.add_resource("wpt.sprite", WAYPOINT_SPRITE.as_bytes().to_vec());
    if let Ok(png) = shadow_image().to_png() {
        vfs.add_resource(SHADOW_IMAGE, png);
    }
}

/// The definition of the fallback font: 256 tiles of 8 by 16 pixels,
/// 32 to a row, every character 8 pixels wide, on a magenta key.
const SYSTEM_FONT_DEFINITION: &str = "FONT\r\n{\r\n  IMAGE = \"system_font.bmp\"\r\n  TRANSPARENT = 255,0,255\r\n  COLUMNS = 32\r\n  TILE_WIDTH = 8\r\n  TILE_HEIGHT = 16\r\n  DEFAULT_WIDTH = 8\r\n}\r\n";

/// The sprite of a waypoint marker: the dot, held by its centre, half
/// transparent.
const WAYPOINT_SPRITE: &str = "SPRITE\r\n{\r\n  LOOPING = FALSE\r\n  FRAME\r\n  {\r\n    IMAGE = \"wpt.bmp\"\r\n    HOTSPOT {4,4}\r\n    ALPHA = 128\r\n  }\r\n}\r\n";

/// The colour key of the generated bitmaps.
const KEY: [u8; 3] = [255, 0, 255];

