/// An opaque image filled with one colour.
fn filled(width: u32, height: u32, color: [u8; 3]) -> Image {
    let mut pixels = Vec::with_capacity((width * height * 4) as usize);
    for _ in 0..width * height {
        pixels.extend_from_slice(&[color[0], color[1], color[2], 255]);
    }
    Image {
        width,
        height,
        pixels,
        has_alpha_channel: false,
    }
}

fn put(image: &mut Image, x: u32, y: u32, color: [u8; 3]) {
    if x < image.width && y < image.height {
        let at = ((y * image.width + x) * 4) as usize;
        image.pixels[at..at + 3].copy_from_slice(&color);
    }
}

/// The tiles of the fallback font: white glyphs on the colour key, the
/// 5x7 letters set one pixel in and five down in their 8x16 tile.
fn system_font_image() -> Image {
    let mut image = filled(256, 128, KEY);
    for (index, glyph) in GLYPHS.iter().enumerate() {
        let code = index as u32 + 32;
        let (tile_x, tile_y) = ((code % 32) * 8, (code / 32) * 16);
        for (row, bits) in glyph.iter().enumerate() {
            for column in 0..5 {
                if bits & (0x10 >> column) != 0 {
                    put(
                        &mut image,
                        tile_x + 1 + column,
                        tile_y + 5 + row as u32,
                        [255, 255, 255],
                    );
                }
            }
        }
    }
    image
}

/// The placeholder of a missing image: a white square, 64 pixels a side,
/// framed and crossed in `color`.
fn invalid_image(color: [u8; 3]) -> Image {
    const SIZE: u32 = 64;
    let mut image = filled(SIZE, SIZE, [255, 255, 255]);
    for i in 0..SIZE {
        for t in 0..2 {
            put(&mut image, i, t, color);
            put(&mut image, i, SIZE - 1 - t, color);
            put(&mut image, t, i, color);
            put(&mut image, SIZE - 1 - t, i, color);
            put(&mut image, (i + t).min(SIZE - 1), i, color);
            put(&mut image, (SIZE - 1 - i + t).min(SIZE - 1), i, color);
        }
    }
    image
}

/// The marker of a waypoint: a red dot of 9 pixels on the colour key.
fn waypoint_image() -> Image {
    let mut image = filled(9, 9, KEY);
    for y in 0..9i32 {
        for x in 0..9i32 {
            if (x - 4).pow(2) + (y - 4).pow(2) <= 17 {
                put(&mut image, x as u32, y as u32, [255, 0, 0]);
            }
        }
    }
    image
}

/// The default shadow: a soft black blob, darkest at the centre and
/// fading to nothing at the edge.
fn shadow_image() -> Image {
    const SIZE: u32 = 64;
    let radius = SIZE as f32 / 2.0;
    let mut pixels = Vec::with_capacity((SIZE * SIZE * 4) as usize);
    for y in 0..SIZE {
        for x in 0..SIZE {
            let (dx, dy) = (x as f32 + 0.5 - radius, y as f32 + 0.5 - radius);
            let fade = (1.0 - (dx * dx + dy * dy).sqrt() / radius).clamp(0.0, 1.0);
            let alpha = fade * fade * (3.0 - 2.0 * fade);
            pixels.extend_from_slice(&[0, 0, 0, (alpha * 192.0).round() as u8]);
        }
    }
    Image {
        width: SIZE,
        height: SIZE,
        pixels,
        has_alpha_channel: true,
    }
}

/// Writes an image as an uncompressed 24-bit BMP file (the alpha channel
/// is dropped).
fn bmp(image: &Image) -> Vec<u8> {
    let (width, height) = (image.width as usize, image.height as usize);
    let stride = (width * 3).div_ceil(4) * 4;
    let data_len = stride * height;
    let mut out = Vec::with_capacity(54 + data_len);
    out.extend_from_slice(b"BM");
    out.extend_from_slice(&(54 + data_len as u32).to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(&54u32.to_le_bytes());
    out.extend_from_slice(&40u32.to_le_bytes());
    out.extend_from_slice(&(width as i32).to_le_bytes());
    out.extend_from_slice(&(height as i32).to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&24u16.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(&(data_len as u32).to_le_bytes());
    out.extend_from_slice(&2835i32.to_le_bytes());
    out.extend_from_slice(&2835i32.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    // Rows from the bottom up, blue first, padded to four bytes.
    for y in (0..height).rev() {
        let row = &image.pixels[y * width * 4..(y + 1) * width * 4];
        for pixel in row.chunks_exact(4) {
            out.extend_from_slice(&[pixel[2], pixel[1], pixel[0]]);
        }
        out.resize(out.len() + stride - width * 3, 0);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use luma_formats::{DEFAULT_COLOR_KEY, FontFile, Rgb, Sprite};

    fn resources() -> Vfs {
        let mut vfs = Vfs::new();
        register(&mut vfs);
        vfs
    }

    #[test]
    fn every_built_in_file_is_served_and_decodes() {
        let vfs = resources();
        for (name, width, height) in [
            ("system_font.bmp", 256, 128),
            ("invalid.bmp", 64, 64),
            ("INVALID_DEBUG.BMP", 64, 64),
            ("wpt.bmp", 9, 9),
            ("shadow.png", 64, 64),
        ] {
            let bytes = vfs.read(name).unwrap_or_else(|e| panic!("{name}: {e}"));
            let image = luma_formats::image::decode(&bytes, DEFAULT_COLOR_KEY)
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!((image.width, image.height), (width, height), "{name}");
        }
        // The placeholder is opaque; the shadow fades out at its corner.
        let invalid =
            luma_formats::image::decode(&vfs.read("invalid.bmp").unwrap(), DEFAULT_COLOR_KEY)
                .unwrap();
        assert_eq!(invalid.pixel(0, 0).unwrap().a, 255);
        assert_eq!(invalid.pixel(32, 20).unwrap().a, 255);
        let shadow =
            luma_formats::image::decode(&vfs.read("shadow.png").unwrap(), DEFAULT_COLOR_KEY)
                .unwrap();
        assert_eq!(shadow.pixel(0, 0).unwrap().a, 0);
        assert!(shadow.pixel(32, 32).unwrap().a > 150);
    }

    /// `CBSprite::LoadFile`, `CBSurfaceStorage::AddSurface`: a sprite or
    /// an image that does not exist is replaced by the placeholder.
    #[test]
    fn a_missing_sprite_or_image_is_the_placeholder() {
        use crate::scene_view::SpriteBank;
        let vfs = resources();
        let mut bank = SpriteBank::new();
        assert!(bank.add_sprite(&vfs, "gone\\thing.sprite"));
        let sprite = &bank.sprite("gone\\thing.sprite").unwrap().sprite;
        assert_eq!(
            sprite.frames[0].subframes[0].image.as_deref(),
            Some(INVALID_IMAGE)
        );
        // The miss is still reported, for the log.
        assert_eq!(bank.missing().len(), 1);
        assert!(bank.add_sprite(&vfs, "gone.png"));
        // An image named by a frame: the placeholder's pixels.
        let mask = bank
            .mask(&vfs, "frames\\gone.png", DEFAULT_COLOR_KEY)
            .unwrap();
        assert_eq!((mask.width, mask.height), (64, 64));

        // Without the engine's files there is nothing to show.
        let bare = Vfs::new();
        let mut bank = SpriteBank::new();
        assert!(!bank.add_sprite(&bare, "gone.sprite"));
    }

    #[test]
    fn the_fallback_font_and_the_waypoint_sprite_load() {
        let vfs = resources();
        let FontFile::Bitmap(font) = FontFile::parse(&vfs.read(SYSTEM_FONT).unwrap()).unwrap()
        else {
            panic!("a bitmap font");
        };
        assert_eq!(font.image.as_deref(), Some("system_font.bmp"));
        assert_eq!(
            (font.columns, font.tile_width, font.tile_height),
            (32, 8, 16)
        );
        // The tiles of the letters hold ink, on the font's colour key.
        let key = font.transparent.unwrap();
        assert_eq!(
            key,
            Rgb {
                r: 255,
                g: 0,
                b: 255
            }
        );
        let image =
            luma_formats::image::decode(&vfs.read("system_font.bmp").unwrap(), key).unwrap();
        let ink = |c: u8| {
            let (x0, y0) = (u32::from(c % 32) * 8, u32::from(c / 32) * 16);
            (0..16)
                .flat_map(|y| (0..8).map(move |x| (x, y)))
                .filter(|(x, y)| image.pixel(x0 + x, y0 + y).is_some_and(|p| p.a > 0))
                .count()
        };
        assert_eq!(ink(b' '), 0);
        for c in b'!'..=b'~' {
            assert!(ink(c) > 0, "{}", char::from(c));
        }
        assert!(ink(b'W') > ink(b'.'));

        let sprite = Sprite::parse(&vfs.read("wpt.sprite").unwrap()).unwrap();
        let sub = &sprite.frames[0].subframes[0];
        assert_eq!(sub.image.as_deref(), Some("wpt.bmp"));
        assert_eq!((sub.hotspot_x, sub.hotspot_y), (4, 4));
        assert_eq!(sub.tint.a, 128);
    }
}
